  if (!json.containsKey(field)) {
    throw ChatEventParseException(
      ChatEventParseErrorCode.malformedEvent,
      'ChatEvent.$field is required.',
    );
  }
  return json[field];
}

String _readEventNonEmptyString(
  Map<String, Object?> json,
  String field,
) {
  final value = _readEventRequired(json, field);
  if (value is! String || value.trim().isEmpty) {
    throw ChatEventParseException(
      ChatEventParseErrorCode.malformedEvent,
      'ChatEvent.$field must be a non-empty string.',
    );
  }
  return value;
}

int _readEventPositiveInt(Map<String, Object?> json, String field) {
  final value = _readEventRequired(json, field);
  if (value is! int || value < 1) {
    throw ChatEventParseException(
      ChatEventParseErrorCode.malformedEvent,
      'ChatEvent.$field must be a positive integer.',
    );
  }
  return value;
}

Object? _freezeJson(Object? value) {
  if (value == null || value is String || value is num || value is bool) {
    return value;
  }
  if (value is List<Object?>) {
    return List<Object?>.unmodifiable(value.map(_freezeJson));
  }
  if (value is Map<Object?, Object?>) {
    final copy = <String, Object?>{};
    for (final entry in value.entries) {
      if (entry.key case final String key) {
        copy[key] = _freezeJson(entry.value);
      } else {
        throw ArgumentError.value(value, 'payload', 'JSON keys must be strings');
      }
    }
    return UnmodifiableMapView(copy);
  }
  throw ArgumentError.value(value, 'payload', 'must be a JSON value');
}

Object? _thawJson(Object? value) {
  if (value is List<Object?>) return value.map(_thawJson).toList();
  if (value is Map<String, Object?>) {
    return value.map((key, item) => MapEntry(key, _thawJson(item)));
  }
  return value;
}
